function addLocale(code,name,row,categories,questions,steps){
 const values=row.split('|'),cats=categories.split('|');
 if(values.length!==KEYS.length||cats.length!==10||questions.length!==10||steps.length!==8)throw Error('Incomplete locale: '+code+' '+values.length+'/'+KEYS.length);
 LANGS[code]=name;UI[code]=Object.fromEntries(KEYS.map((key,i)=>[key,values[i]]));CAT[code]=cats;FAQ[code]=questions;STEPS[code]=steps;
}
